import app from 'flarum/admin/app';
import UploadImageButton from 'flarum/common/components/UploadImageButton';
import Button from 'flarum/common/components/Button';
import classList from 'flarum/common/utils/classList';
export default class PWALogoUploadButton extends UploadImageButton {
  get size() {
    return this.attrs.size;
  }
  get name() {
    return `pwa-icon-${this.size}x${this.size}`;
  }
  oninit(vnode) {
    super.oninit(vnode);
  }
  upload() {
    if (this.loading) return;
    const $input = $('<input type="file">');
    $input.appendTo('body').hide().trigger('click').on('change', e => {
      const body = new FormData();
      body.append(this.name, $(e.target)[0].files[0]);
      this.loading = true;
      m.redraw();
      app.request({
        method: 'POST',
        url: this.resourceUrl(),
        body
      }).then(() => this.success({}), () => this.failure({}));
    });
  }
  view() {
    const attrs = this.attrs;
    attrs.loading = this.loading;
    attrs.className = classList(attrs.className, 'Button');
    const settingKey = `fof-pwa.icon_${this.size}_path`;
    const hasImage = app.data.settings[settingKey];
    if (hasImage) {
      attrs.onclick = this.remove.bind(this);
      return m("div", null, m("p", null, m("img", {
        src: app.forum.attribute(`pwa-icon-${this.size}x${this.size}Url`),
        alt: ""
      })), m("p", null, m(Button, attrs, app.translator.trans('core.admin.upload_image.remove_button'))));
    }
    attrs.onclick = this.upload.bind(this);
    return m(Button, attrs, app.translator.trans('core.admin.upload_image.upload_button'));
  }
  resourceUrl() {
    return app.forum.attribute('apiUrl') + '/pwa/logo/' + this.size;
  }
}
flarum.reg.add('fof-pwa', 'admin/components/PWALogoUploadButton', PWALogoUploadButton);